def predict(board, action):
    if isinstance(action, tuple):
        row, col = action
    else:
        return board

    new_board = [list(row) for row in board]

    if row < 0 or row >= 64 or col < 0 or col >= 64:
        return board

    char = new_board[row][col]

    if char == 'W':
        new_board[row][col] = 'S'
        for r in range(max(0, row-1), min(64, row+2)):
            for c in range(max(0, col-1), min(64, col+2)):
                if new_board[r][c] == 'W':
                    new_board[r][c] = 'S'
    elif char == 'S':
        new_board[row][col] = 'R'
        for r in range(max(0, row-1), min(64, row+2)):
            for c in range(max(0, col-1), min(64, col+2)):
                if new_board[r][c] == 'S':
                    new_board[r][c] = 'R'
    elif char == 'R':
        new_board[row][col] = 'S'

    return [''.join(row) for row in new_board]
